  "mentions-input": {"usage":{"lang":"svelte","code":"<script lang=\"ts\">\n  import MentionsInput from './MentionsInput.svelte';\n\n  let value = $state('');\n  let expanded = $state(false);\n\n  function handleInput(e: Event) {\n    const input = e.target as HTMLInputElement;\n    value = input.value;\n    expanded = input.value.endsWith('@');\n  }\n</script>\n\n<MentionsInput\n  label=\"Comment\"\n  value={value}\n  expanded={expanded}\n  oninput={handleInput}\n  placeholder=\"Type @ to mention\"\n>\n  <ul role=\"listbox\" aria-label=\"People\">\n    <li role=\"option\" aria-selected=\"false\">@alice</li>\n  </ul>\n</MentionsInput>\n"}},
